package com.infinitylibrary.builder;

import com.google.gson.*;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.gui.screens.ConfirmScreen;
import net.minecraft.client.gui.GuiGraphicsExtractor;
import net.minecraft.client.gui.components.*;
import net.minecraft.network.chat.Component;

/** Compact native screen: room browser, all wand tools/settings, and live in-world preview controls. */
public final class BuilderScreen extends Screen {
    public static final class Options{String room="my_room",selected="",type="FILLER",category="general",area="area_1",variant="variant_1",weight="1",gap="0",floor="0",direction="NORTH",connection="door";int tab;boolean rotate=true,stack;String fill="EXACT";}
    private final Options o=BuilderClient.options;private EditBox room,category,area,variant,weight,gap,floor,connection;private boolean rebuilding;
    public BuilderScreen(){super(Component.literal("Infinity Library Builder"));}
    private Button button(int x,int y,int width,String text,Runnable action){return addRenderableWidget(Button.builder(Component.literal(text),b->{remember();action.run();}).bounds(x,y,width,20).build());}
    private EditBox field(int x,int y,int width,String value,String hint,int max){EditBox box=new EditBox(font,x,y,width,20,Component.literal(hint));box.setMaxLength(max);box.setValue(value);box.setHint(Component.literal(hint));addRenderableWidget(box);return box;}
    @Override protected void init(){build();}
    public void remember(){if(rebuilding)return;if(room!=null)o.room=room.getValue();if(category!=null)o.category=category.getValue();if(area!=null)o.area=area.getValue();if(variant!=null)o.variant=variant.getValue();if(weight!=null)o.weight=weight.getValue();if(gap!=null)o.gap=gap.getValue();if(floor!=null)o.floor=floor.getValue();if(connection!=null)o.connection=connection.getValue();}
    public void stateChanged(){build();}
    private void build(){rebuilding=true;clearWidgets();room=category=area=variant=weight=gap=floor=connection=null;int tabWidth=(width-24)/4;String[] tabs={"Rooms","Tools","Settings","Preview"};for(int i=0;i<4;i++){int index=i;button(12+i*tabWidth,28,tabWidth-3,(o.tab==i?"• ":"")+tabs[i],()->{o.tab=index;build();});}switch(o.tab){case 0->rooms();case 1->tools();case 2->settings();default->preview();}button(width-90,height-26,78,"Close",this::onClose);button(12,height-26,90,"Refresh",BuilderClient::hello);rebuilding=false;}
    private void rooms(){int half=width/2;JsonArray list=BuilderClient.state.has("rooms")?BuilderClient.state.getAsJsonArray("rooms"):new JsonArray();for(int i=0;i<list.size()&&i<6;i++){JsonObject r=list.get(i).getAsJsonObject();String id=r.get("id").getAsString();button(12,62+i*21,half-20,id,()->{JsonObject a=new JsonObject();a.addProperty("room",id);BuilderClient.send("select",a);});}int page=BuilderClient.state.has("page")?BuilderClient.state.get("page").getAsInt():0;button(12,Math.min(190,height-52),64,"‹ Page",()->page(page-1));button(82,Math.min(190,height-52),64,"Page ›",()->page(page+1));int x=half+6,w=width-x-12;room=field(x,66,w,o.room,"Room ID",64);button(x,92,w,"Type: "+o.type,()->{String[] types={"FILLER","BOOK","READ","STARTING"};for(int i=0;i<types.length;i++)if(types[i].equals(o.type)){o.type=types[(i+1)%types.length];break;}build();});button(x,118,w,"Load areas into selection",()->roomAction("load"));button(x,144,w,"Save selected build as room",()->confirmSave());button(x,170,w,"Preview saved room",()->roomAction("preview"));}
    private void page(int page){JsonObject p=new JsonObject();p.addProperty("page",Math.max(0,page));BuilderClient.send("refresh",p);}
    private void roomAction(String action){JsonObject a=new JsonObject();a.addProperty("room",o.room);BuilderClient.send(action,a);}
    private void confirmSave(){String expected="";if(BuilderClient.state.has("detail")){JsonObject d=BuilderClient.state.getAsJsonObject("detail");if(d.get("id").getAsString().equals(o.room))expected=d.get("version").getAsString();}final String version=expected;boolean replace=!expected.isEmpty();minecraft.setScreenAndShow(new ConfirmScreen(ok->{if(ok){JsonObject a=new JsonObject();a.addProperty("room",o.room);a.addProperty("type",o.type);a.addProperty("expected",version);BuilderClient.send("save",a);}minecraft.setScreenAndShow(this);},Component.literal(replace?"Replace unused template?":"Save room template?"),Component.literal("Save "+o.room+" as "+o.type+". Built templates remain protected.")));}
    private void tools(){String[] kinds={"room","connection","decoration","diversity","diversity_connection","variation","shelf","table","seat"};int w=(width-32)/3;for(int i=0;i<kinds.length;i++){String kind=kinds[i];button(12+(i%3)*(w+4),64+(i/3)*26,w,kind.replace('_',' '),()->{if(kind.equals("diversity_connection")){o.tab=2;build();return;}JsonObject a=new JsonObject();a.addProperty("tool",kind);BuilderClient.send("tool",a);minecraft.setScreenAndShow(null);});}int y=156;button(12,y,82,"Undo",()->BuilderClient.send("undo"));button(98,y,82,"Redo",()->BuilderClient.send("redo"));button(184,y,100,"Cancel corner",()->BuilderClient.send("cancel"));button(12,184,140,"Apply reading/shelf regions",()->BuilderClient.send("apply"));button(158,184,120,"Outlines: "+BuilderClient.outlines,()->{BuilderClient.outlines=!BuilderClient.outlines;build();});button(284,184,Math.max(80,width-296),"X-ray: "+BuilderClient.throughWalls,()->{BuilderClient.throughWalls=!BuilderClient.throughWalls;build();});}
    private void settings(){int w=(width-36)/3;category=field(12,66,w,o.category,"Category",64);area=field(18+w,66,w,o.area,"Area / prefix",48);variant=field(24+w*2,66,w,o.variant,"Variant",64);weight=field(12,100,w,o.weight,"Weight",12);gap=field(18+w,100,w,o.gap,"Gap %",8);floor=field(24+w*2,100,w,o.floor,"Floor index",8);button(12,132,w,"Set area category",()->request("category"));button(18+w,132,w,"Decoration settings",()->request("prop_settings"));button(24+w*2,132,w,"Diversity target",()->request("diversity_settings"));button(12,158,w,"Add variant source",()->request("diversity_variant"));button(18+w,158,w,"Direction: "+o.direction,()->{String[] ds={"NORTH","EAST","SOUTH","WEST","UP","DOWN"};for(int i=0;i<ds.length;i++)if(ds[i].equals(o.direction)){o.direction=ds[(i+1)%ds.length];break;}build();});button(24+w*2,158,w,"Variant door wand",()->request("diversity_connection"));button(12,184,w,"Rotate props: "+o.rotate,()->{o.rotate=!o.rotate;build();});button(18+w,184,w,o.fill,()->{o.fill=o.fill.equals("EXACT")?"PACKED":"EXACT";build();});button(24+w*2,184,w,BuilderClient.text("tool").equals("variation")?"Variation settings":"Connection prefix",()->request(BuilderClient.text("tool").equals("variation")?"variation_settings":"connection_settings"));}
    private void request(String action){JsonObject a=new JsonObject();a.addProperty("category",o.category);a.addProperty("area",o.area);a.addProperty("variant",o.variant);a.addProperty("connection",o.connection);a.addProperty("direction",o.direction);a.addProperty("fill",o.fill);a.addProperty("rotate",o.rotate);a.addProperty("stack",o.stack);try{a.addProperty("weight",Double.parseDouble(o.weight));a.addProperty("gap",Double.parseDouble(o.gap));a.addProperty("floor",Integer.parseInt(o.floor));}catch(NumberFormatException ex){BuilderClient.error="Weight, gap and floor must be numbers.";return;}BuilderClient.send(action,a);}
    private void preview(){int x=12,w=(width-32)/2;room=field(x,66,width-24,o.room,"Saved room ID",64);button(x,90,w,"Start live room preview",()->roomAction("preview"));button(x+w+8,90,w,"Inspect in world",this::onClose);button(x,116,w,"Rotate 90°",()->BuilderClient.send("preview_rotate"));button(x+w+8,116,w,"Mirror X",()->BuilderClient.send("preview_mirror"));button(x,142,w,"Reroll props / Diversity",()->BuilderClient.send("preview_reroll"));button(x+w+8,142,w,"Stop preview",()->BuilderClient.send("preview_stop"));area=field(x,168,w,o.area,"Diversity area",48);variant=field(x+w+8,168,w,o.variant,"Variant / default",64);button(x,194,w,"Show variant",()->{JsonObject a=new JsonObject();a.addProperty("area",o.area);a.addProperty("variant",o.variant);BuilderClient.send("preview_variant",a);});}
    @Override public void extractRenderState(GuiGraphicsExtractor g,int mouseX,int mouseY,float delta){g.fill(4,4,width-4,height-4,0xd90c1721);g.fill(4,4,width-4,23,0xff173342);g.text(font,"INFINITY LIBRARY  /  BUILDER",12,10,0xff8ce5d0);String status=BuilderClient.error.isEmpty()?BuilderClient.text("prompt"):BuilderClient.error;g.text(font,font.plainSubstrByWidth(status,width-24),12,52,BuilderClient.error.isEmpty()?0xffb6c9d6:0xffff9a88);super.extractRenderState(g,mouseX,mouseY,delta);}
    @Override public boolean isPauseScreen(){return false;}
    @Override public void onClose(){remember();minecraft.setScreenAndShow(null);}
}
